import sqlite3
import sys
import html

def parse_arguments():
    args = sys.argv[1:]
    db_path = args[0]
    table_name = args[1]
    where_clauses = []
    output_path = None

    i = 2
    while i < len(args):
        arg = args[i]
        if arg == '--where':
            if i + 1 >= len(args):
                raise ValueError("Missing value for --where clause")
            column_value = args[i+1].split('=', 1)
            if len(column_value) != 2:
                raise ValueError("Invalid --where format: COLUMN=VALUE")
            where_clauses.append((column_value[0], column_value[1]))
            i += 2
        elif arg == '--out':
            if i + 1 >= len(args):
                raise ValueError("Missing output path for --out")
            output_path = args[i+1]
            i += 2
        else:
            raise ValueError(f"Unknown argument: {arg}")
    if output_path is None:
        raise ValueError("--out argument is required")
    return db_path, table_name, where_clauses, output_path

def build_where_clause(where_clauses):
    clauses = []
    for column, value in where_clauses:
        clauses.append(f"{column} = ?")
    return " AND ".join(clauses)

def generate_html_table(rows, columns):
    html_content = ["<!DOCTYPE html>", "<html>", "<body>"]

    # Header row
    header_row = ["<th>"] + [html.escape(col) for col in columns]
    header_row.append("</th>")
    html_content.append("".join(header_row))

    # Data rows
    for row in rows:
        row_row = ["<tr>"]
        for value in row:
            if value is None:
                row_row.append("<td></td>")
            else:
                row_row.append(f"<td>{html.escape(str(value))}</td>")
        row_row.append("</tr>")
        html_content.append("".join(row_row))

    html_content.extend(["</body>", "</html>"])
    return "\n".join(html_content)

def main():
    try:
        db_path, table_name, where_clauses, output_path = parse_arguments()

        # Connect to the database
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Build WHERE clause
        where_clause = build_where_clause(where_clauses)
        if where_clauses:
            cursor.execute(f"SELECT * FROM {table_name} WHERE {where_clause}", where_clauses)
        else:
            cursor.execute(f"SELECT * FROM {table_name}")

        # Fetch all columns and rows
        columns = [desc[0] for desc in cursor.description]
        rows = cursor.fetchall()

        # Generate HTML
        html_output = generate_html_table(rows, columns)

        # Write to output file
        with open(output_path, 'w') as f:
            f.write(html_output)

    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if 'conn' in locals():
            conn.close()

if __name__ == "__main__":
    main()
